fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Ensure the inputs are of the same length.
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );

    // Zip the two vectors together, perform bitwise AND on each pair,
    // and collect the results into a new vector.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}

fn main() {
    let v1 = vec![0b10101010, 0b11110000, 0b00001111];
    let v2 = vec![0b11001100, 0b10101010, 0b11110000];

    let result = bitwise_and(v1, v2);
    println!("{:08b?}", result);
    // Output should be: ["10001000", "10100000", "00000000"]
}